const charts=new Map(),chartMetadata=new Map(),comparisonCache=new Map(),comparisonPending=new Map();let replayTimer=null,stream=null,pollTimer=null,reloadTimer=null,loading=false,pendingLoad=false,chartRequest=0;
state.selectionInitialized=false;state.replayMode=false;state.replaySpeed=1;state.strengthFrame=null;state.moverFrame=null;state.moverPending=false;state.openSeries=new Map();state.openRenderAt=0;
state.compareGroup='all';state.comparePool='quote';state.comparePeriod='intraday';state.followQuoteLeaders=true;state.trendPositions=new Map();state.trendPositionsLoading=false;
state.followObservationPool=true;state.latestFire=null;state.fireVersion=0;state.fireDirty=false;state.lastLoadedAt=0;
