function toast(text){$('#toast').textContent=text;$('#toast').className='show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').className='',4500)}
async function api(path,body,{signal}={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('/api/market-panorama/'+path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),signal:signal?AbortSignal.any([signal,controller.signal]):controller.signal});const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data}catch(e){if(signal?.aborted)throw e;if(e.name==='AbortError')throw Error('数据读取超时，请重试');throw e}finally{clearTimeout(timer)}}
function icons(){window.lucide?.createIcons()}
function list({ignoreSector=false}={}){return(state.snapshot?.products||[]).filter(p=>(state.scope==='all'||state.scope==='commodity'&&p.exchange!=='CFFEX'||state.scope==='financial'&&p.exchange==='CFFEX'||state.scope==='watch'&&state.snapshot.watchlist.includes(p.code))&&(ignoreSector||state.sector==='all'||p.sector===state.sector)&&(!state.search||[p.code,p.name,p.contract].some(v=>String(v||'').toLowerCase().includes(state.search.toLowerCase()))))}
function strengthUniverse(){return list({ignoreSector:true})}
function currentPool(){if(state.replayMode&&state.replayPool)return state.replayPool;if(state.comparePool==='quote')return openObservationPool(strengthUniverse(),state.openSeries,{date:state.date,cutoff:state.replayMode?state.strengthCutoff:undefined});return observationPool(strengthUniverse(),state.comparePool,state.date,{fireAsOf:state.snapshot?.fireAsOf})}
function comparisonProducts(){const rows=currentPool().rows.filter(p=>state.compareGroup==='all'||strengthSectorFor(p)===state.compareGroup);return state.compareOrder==='default'?rows:sortPanoramaComparison(rows,state.compareOrder)}
function choosePool(key){state.comparePool=key;state.compareOrder='default';state.followQuoteLeaders=key==='quote';state.followObservationPool=true;const pool=currentPool(),rows=comparisonProducts();state.selected=new Set(defaultPoolSelection({...pool,rows,long:rows.filter(p=>p.observation?.side==='long'),short:rows.filter(p=>p.observation?.side==='short')}));state.selectionInitialized=true;state.playing=false;clearInterval(replayTimer);render()}
function sort(rows,key=state.sort||'code'){return orderedRows(rows,key,state.sortAsc)}
function table(columns,rows,{sortable=true,id,preserveOrder=false}={}){
 id=id||`${state.page}Table${++tableIndex}`;
 const productRows=rows.length>0&&rows.every(r=>typeof r.code==='string'),order=state.tableSort[id];
 if(order)rows=orderedRows(rows,order.key,order.ascending);
 else if(!preserveOrder){if(productRows)rows=sortPanoramaProducts(rows);else if(rows.length&&rows.every(r=>strengthSectors.includes(r.name)))rows=[...rows].sort((a,b)=>strengthSectors.indexOf(a.name)-strengthSectors.indexOf(b.name))}
 return `<div class="table-wrap${productRows?' product-table':''}"><table id="${id}"><thead><tr>${columns.map(([label,key])=>`<th ${order?.key===key?'aria-sort="'+(order.ascending?'ascending':'descending')+'"':''}>${sortable&&key?`<button data-sort="${key}" data-table="${id}" title="按${label.replace(/<[^>]+>/g,'')}排序">${label}${icon(order?.key===key?(order.ascending?'arrow-up':'arrow-down'):'arrow-down-up')}</button>`:label}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map((row,index)=>`<tr${productRows?` data-product-code="${esc(row.code)}"`:''}>${columns.map(([,key,render])=>`<td>${render?render(row.displayRank?{...row,displayRank:index+1}:row):esc(row[key])}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}"><div class="empty">${state.snapshot?.job?.status==='running'?'数据正在同步，已有结果会保留':'当前筛选没有可用数据'}</div></td></tr>`}</tbody></table></div>`;
}
const sectorTag=p=>{const label=p.code?strengthSectorFor(p):p.sector;return `<span class="sector-tag ranking-sector-tag" data-sector="${esc(label)}">${esc(label)}</span>`};
const nameCell=p=>`<div class="product-identity"><button class="name-button" data-product="${esc(p.code)}" title="${esc(p.contract||'合约待核')} · ${esc(p.changeBasis?'涨跌基准：'+p.changeBasis:'涨跌基准待核')} · 查看品种详情"><b class="product-code">${esc(p.code)}</b><span>${esc(p.name)}</span></button>${sectorTag(p)}</div>`;
const nameColumn=['品种','name',nameCell];
const signalCell=(p,key)=>{const s=p.signals[key],a=signalAppearance(s),label=panoramaPeriods.find(x=>x.key===key)?.label;return`<button class="signal-badge ${a.tone}" data-signal="${esc(p.code)}" data-period-key="${key}" aria-label="${esc(p.code+' '+p.name+' '+label+' '+a.label+'，查看依据')}" title="${esc((s?.stamp||'日期待核')+' · 点击查看EMA10与价格依据')}">${a.label}</button>`};
const amountColumn=['净名义金额','amount',p=>`<span class="${tone(p.amount)}">${money(p.amount)}</span><small>公开双侧样本 ${p.seatCoverage.complete}/${p.seatCoverage.pairs}</small>`];
const actions=p=>`<button title="查看品种复盘" data-product="${p.code}">${icon('crosshair')}</button><button title="${state.snapshot.watchlist.includes(p.code)?'移出':'加入'}自选" data-watch="${p.code}">${icon(state.snapshot.watchlist.includes(p.code)?'star-off':'star')}</button>`;
function section(title,content,subtitle='',action=''){return`<section class="section"><div class="section-head"><div><h2>${title}</h2>${subtitle?`<small>${subtitle}</small>`:''}</div>${action}</div>${content}</section>`}
function stats(items){return`<div class="stats${items.length===5?' five-periods':''}">${items.map(([title,value,note,cls=''])=>`<div class="stat"><small>${title}</small><strong class="${cls}">${value}</strong><span>${note}</span></div>`).join('')}</div>`}
function chips(items,value,attr){return`<div class="chips">${items.map(([key,label])=>`<button class="${value===key?'active':''}" aria-pressed="${value===key}" ${attr}="${key}">${label}</button>`).join('')}</div>`}
function note(text,warning=false){return`<div class="note${warning?' warning':''}">${text}</div>`}
function chart(id,cls=''){return`<div class="chart-tools"><button data-fullscreen="${id}" title="全屏查看">${icon('maximize')}</button><button data-image="${id}" title="导出图表到项目">${icon('image-down')}</button><button data-copy-image="${id}" title="复制图表">${icon('copy')}</button></div><div id="${id}" data-chart class="chart ${cls}" role="img" aria-label="${id==='strengthChart'?'品种强弱对比':'市场数据走势图'}"></div>`}
function periodPicker(){return`<div class="chart-options"><select id="pricePeriod" aria-label="价格图周期">${panoramaPeriods.map(p=>`<option value="${p.period}" ${state.period===p.period?'selected':''}>${p.label} EMA10</option>`).join('')}</select></div>`}
function productPicker({fees=false}={}){
 const universe=sortPanoramaProducts(list()),current=universe.find(p=>p.code===state.product);
 const requested=(fees?state.feeSector:state.detailSector)??(current?strengthSectorFor(current):'all');
 const sector=requested==='all'||universe.some(p=>strengthSectorFor(p)===requested)?requested:'all';
 const rows=universe.filter(p=>sector==='all'||strengthSectorFor(p)===sector),selected=fees?state.feeProduct:state.product;
 const boards=[['all','全部板块'],...strengthSectors.filter(s=>universe.some(p=>strengthSectorFor(p)===s)).map(s=>[s,s])];
 return `<section class="product-selector" aria-label="品种选择"><header><h2>品种选择</h2><span>选择后，下方图表${fees?'与费用':''}同步更新</span></header><div class="picker-row"><strong>板块选择</strong><div class="picker-boards">${boards.map(([key,label])=>`<button data-picker-sector="${esc(key)}" aria-pressed="${sector===key}" class="${sector===key?'active':''}">${esc(label)}</button>`).join('')}</div></div><div class="picker-row"><strong>品种选择</strong><div class="picker-products">${fees?`<button data-fee-product="all" class="${!selected?'active':''}" aria-pressed="${!selected}">全部品种</button>`:''}${rows.map(p=>`<button ${fees?'data-fee-product':'data-pick'}="${p.code}" aria-pressed="${selected===p.code}" class="${selected===p.code?'active':''}"><b class="product-code">${esc(p.code)}</b> ${esc(p.name)}</button>`).join('')||'<span class="caption">当前筛选没有品种</span>'}</div></div></section>`;
}
function detailPlaceholder(){return productPicker()+`<div class="empty">${!state.product?'当前筛选没有可研究的品种':state.detailError?`<div>${esc(state.detailError)}<p><button data-retry-detail>${icon('refresh-cw')}重试读取</button></p></div>`:'正在读取品种数据…'}</div>`}
function clearDetail(){state.detail=null;state.detailError=null;state.members.clear();state.detailRequest++;chartRequest++;for(const id of ['priceChart','fundChart','positionChart']){charts.get(id)?.clear();chartMetadata.delete(id)}}
function syncProduct(){if(!['funds','positions','variety'].includes(state.page))return false;const rows=list();if(rows.some(p=>p.code===state.product))return false;state.product=rows[0]?.code||null;clearDetail();return true}
function filterChanged(){const changed=syncProduct();if(!list().some(p=>p.code===state.feeProduct))state.feeProduct=null;if(state.detailSector!=='all'&&!list().some(p=>strengthSectorFor(p)===state.detailSector))state.detailSector=null;if(state.feeSector&&state.feeSector!=='all'&&!list().some(p=>strengthSectorFor(p)===state.feeSector))state.feeSector='all';render();if(changed&&state.product)void loadDetail()}
function scopeGroups(){const map=new Map();for(const p of list()){if(!map.has(p.sector))map.set(p.sector,[]);map.get(p.sector).push(p)}return [...map].map(([name,items])=>{const counts={};for(const {key} of panoramaPeriods){const valid=items.filter(p=>['long','short'].includes(p.signals[key].side));counts[key]=valid.length?valid.filter(p=>p.signals[key].side==='long').length/valid.length*100:null}const values=Object.values(counts).filter(v=>v!==null);return{name,items,total:items.length,...counts,score:values.length?values.reduce((a,b)=>a+b,0)/values.length:null}})}
function renderHome(){
 const rows=list();
 if(state.homeSector!=='all'&&!rows.some(p=>strengthSectorFor(p)===state.homeSector))state.homeSector='all';
 return renderCloseHome({products:rows,overview:state.snapshot.closeOverview,sector:state.homeSector,exchange:state.homeExchange,order:state.homeOrder,busy:state.refreshPending||state.snapshot.job?.status==='running'})+
 section('重点变化',table([nameColumn,['日K EMA10','',p=>signalCell(p,'day')],['量变（完成日K）','volumeChange',p=>`<span class="${tone(p.volumeChange)}">${n(p.volumeChange)}</span>`],['仓变（完成日K）','interestChange',p=>`<span class="${tone(p.interestChange)}">${n(p.interestChange)}</span>`],['席位净仓变化','delta',p=>`<span class="${tone(p.delta)}">${n(p.delta)} 手</span>`],['操作','',actions]],orderedRows(rows.filter(p=>p.delta!==null),'delta').slice(0,12),{id:'homeChanges',preserveOrder:true}),`按席位净仓变化降序 · 公开排名 ${state.snapshot.seatDate||'待同步'}`);
}
function showCloseEvidence(code){const p=closeRows(state.snapshot.products,state.snapshot.closeOverview).find(p=>p.code===code);if(!p)return;$('#detailTitle').textContent=p.code+' '+p.name+' · 收盘依据';$('#detailBody').innerHTML=closeDetail(p);$('#detailDialog').showModal()}
function showSignal(code,key){
 const p=state.snapshot?.products.find(p=>p.code===code),s=p?.signals[key],period=panoramaPeriods.find(x=>x.key===key);if(!s||!period)return;
 const a=signalAppearance(s),slope=typeof s.maChange==='number'?(Math.abs(s.maChange)<1e-9?'走平':s.maChange>0?'上升':'下降'):'待核验';
 $('#detailTitle').textContent=`${p.code} ${p.name} · ${period.label} ${a.label}`;
 const facts=[['完成K线收盘',n(s.close,3)],['EMA10',n(s.ma,3)],['前一根EMA10',n(s.previousMa,3)],['EMA10方向',slope],['有效样本',n(s.samples)+' 根'],['K线截止',s.stamp||'日期待核']];
 $('#detailBody').innerHTML=`<div class="signal-facts">${facts.map(([label,value])=>`<div><small>${label}</small><b>${esc(value)}</b></div>`).join('')}</div><p>价格相对EMA10：${direction(s.side)}；${esc(s.reason||'价格位置与EMA10方向共同决定显示深浅，不改变原筛选资格。')}</p><p>来源：${esc(s.source||'来源待核验')} · ${esc(s.contract||(['month','week','day'].includes(key)?'完成主连序列':p.contract||'合约待核'))}</p>${a.label==='待核'?note('当前EMA10方向数据不足，暂不标强弱；至少需要11根有效完成K线。'):''}<button class="primary" data-product="${esc(p.code)}" data-signal-detail>查看品种完整详情 ${icon('arrow-right')}</button>`;
 $('#detailDialog').showModal();icons();
}
function renderSectorButtons(){
 const visible=['overview','rankings'].includes(state.page);$('#sectorFilter').hidden=visible||['strength','funds','positions','fees','variety'].includes(state.page);$('#sectorButtons').hidden=!visible;
 if(visible)$('#sectorButtons').innerHTML=`<strong>板块选择</strong><div role="group" aria-label="板块选择">${[['all','全部'],...strengthSectors.map(s=>[s,s])].map(([key,label])=>`<button data-sector-filter="${esc(key)}" aria-pressed="${state.sector===key}" class="${state.sector===key?'active':''}">${esc(label)}</button>`).join('')}</div>`;
}
const cycleTone=ratio=>ratio===null?'unknown':ratio>50?'bull':ratio<50?'bear':'balanced';
function cycleCountTitle(c){return `多头 ${c.long} / 空头 ${c.short} / 平衡 ${c.flat} / 缺失 ${c.missing}；多头占比以多＋空 ${c.valid} 个为分母；K线截止 ${c.earliest||'未知'}${c.earliest!==c.latest&&c.latest?' 至 '+c.latest:''}`}
function renderCycleDashboard(rows){
 const cards=panoramaPeriods.map(({key,label})=>{const c=periodCounts(rows,key);return `<article class="cycle-stat ${cycleTone(c.ratio)}" data-cycle-stat="${key}"><div class="cycle-stat-title"><h3>${label}</h3><span>${balanceLabel(c.ratio)}</span></div><div class="cycle-ratio"><b>${c.ratio===null?'未取得':c.ratio.toFixed(1)+'%'}</b><span>多头占比</span></div><div class="cycle-counts" title="${esc(cycleCountTitle(c))}"><div><small>多头</small><b class="long">${c.long}</b></div><div><small>空头</small><b class="short">${c.short}</b></div><div><small>有效样本</small><b>${c.valid}</b></div></div><small class="cycle-coverage">总数 ${c.total} · 平衡 ${c.flat} · 缺失 ${c.missing}</small><small class="cycle-cutoff" title="${esc(cycleCountTitle(c))}">K线截止 ${esc(c.latest||'待同步')}${c.earliest!==c.latest?' · 日期不齐':''}</small></article>`}).join('');
 const groups=sortSectorCycles(sectorCycleStats(rows,{sectors:strengthSectors,sectorFor:strengthSectorFor}),state.cycleSort,state.cycleAscending,strengthSectors),focused=groups.find(g=>g.name===state.overviewSector)||groups[0];
 const options=[['score','综合多头占比'],['default','默认板块顺序'],['total','品种数量'],...panoramaPeriods.map(p=>[p.key,p.label+'多头占比'])];
 const sortControls=`<div class="cycle-sort"><label for="cycleSectorSort">排序</label><select id="cycleSectorSort">${options.map(([key,label])=>`<option value="${key}" ${state.cycleSort===key?'selected':''}>${label}</option>`).join('')}</select><button data-cycle-sort-direction title="${state.cycleAscending?'当前升序，点击降序':'当前降序，点击升序'}" aria-label="切换板块排序方向" ${state.cycleSort==='default'?'disabled':''}>${icon(state.cycleAscending?'arrow-up':'arrow-down')}</button></div>`;
 const distribution=`<div class="cycle-distribution-wrap"><table class="cycle-distribution"><thead><tr><th>序号</th><th>板块</th><th>品种</th><th>周期结构</th>${panoramaPeriods.map(p=>`<th><button data-cycle-sort="${p.key}" title="按${p.label}多头占比排序">${p.label}${icon(state.cycleSort===p.key?(state.cycleAscending?'arrow-up':'arrow-down'):'arrow-down-up')}</button></th>`).join('')}</tr></thead><tbody>${groups.map((g,i)=>`<tr data-cycle-sector-row="${esc(g.name)}" class="${focused===g?'selected':''}"><td>${i+1}</td><td><button data-overview-sector="${esc(g.name)}" aria-pressed="${focused===g}">${esc(g.name)}</button></td><td>${g.items.length}</td><td><span class="cycle-structure ${g.structure==='五周期偏多'?'bull':g.structure==='五周期偏空'?'bear':'balanced'}" title="${g.score===null?'部分周期无多空样本，不参与综合排名':`五周期多头占比等权平均 ${g.score.toFixed(1)}%`}">${g.structure}</span></td>${panoramaPeriods.map(({key})=>{const c=g.periods[key];return `<td title="${esc(cycleCountTitle(c))}"><div class="cycle-meter ${cycleTone(c.ratio)}"><progress max="100" value="${c.ratio??0}" aria-label="${esc(g.name+' '+key+' 多头占比')}" ${c.ratio===null?'hidden':''}></progress><b>${c.ratio===null?'未取得':Math.round(c.ratio)+'%'}</b></div></td>`}).join('')}</tr>`).join('')||'<tr><td colspan="9"><div class="empty">当前筛选没有品种</div></td></tr>'}</tbody></table></div>`;
 const groupNote={'全红共振':'五周期同向偏多','全绿共振':'五周期同向偏空','逆市诱多':'月周空 · 日时多','逆市诱空':'月周多 · 日时空','混沌分歧':'方向存在分歧','数据不足':'等待补齐数据'};
 const groupPanels=focused?`<div class="cycle-classifications">${resonanceLabels.map(label=>{const items=focused.groups[label],closed=state.closedCycleGroups.has(label),cls=['全红共振','逆市诱多'].includes(label)?'bull':['全绿共振','逆市诱空'].includes(label)?'bear':'balanced';return `<section class="cycle-classification ${cls}" data-cycle-class="${label}"><button class="cycle-class-title" data-cycle-group="${label}" aria-expanded="${!closed}"><b>${label}</b><span>${groupNote[label]}</span><small>${items.length}</small>${icon(closed?'chevron-right':'chevron-down')}</button><div class="cycle-class-products" ${closed?'hidden':''}>${items.map(p=>`<button data-product="${esc(p.code)}" title="${esc(p.contract||'合约待核')} · 查看品种详情"><b>${esc(p.code)}</b> ${esc(p.name)}</button>`).join('')||'<span class="cycle-empty">该板块暂无此类品种</span>'}</div></section>`}).join('')}</div>`:'<div class="empty">没有可分类的品种</div>';
 const generated=state.snapshot.generatedAt?new Date(state.snapshot.generatedAt).toLocaleString('zh-CN',{hour12:false}):'待同步';
 return `<section class="cycle-dashboard" aria-label="周期统计与板块分布"><header class="cycle-dashboard-head"><div><h2>周期统计</h2><span>当前筛选 ${rows.length} 个品种</span><button data-cycle-info aria-label="查看周期统计口径" title="多头占比与排序口径">${icon('info')}</button></div><div class="cycle-update"><span>页面更新 <time>${esc(generated)}</time></span><button data-cycle-refresh ${state.snapshot.job?.status==='running'?'disabled':''}>${icon('refresh-cw')}<span>${state.snapshot.job?.status==='running'?'同步中':'刷新'}</span></button></div></header><div class="cycle-stat-grid">${cards}</div><div class="cycle-distribution-grid"><section class="cycle-panel"><header><div><h3>板块周期分布</h3><small>点击板块，右侧查看对应品种</small></div>${sortControls}</header>${distribution}</section><section class="cycle-panel"><header><div><h3>${esc(focused?.name||'板块')} · 共振类型品种</h3><small>全部分类 ${focused?.items.length||0} 个 · 点击品种查看详情</small></div></header>${groupPanels}</section></div><p class="cycle-stat-note">多头占比＝多头÷（多头＋空头），平衡和缺失单列；板块综合排序取五周期占比等权平均，缺少周期则排末尾。统计为当前样本分布，不是板块指数。</p></section>`;
}
function showCycleInfo(){
 $('#detailTitle').textContent='周期统计口径';$('#detailBody').innerHTML='<p>沿用小木现有月K、周K、日K、2小时、30分钟EMA10方向：收盘高于EMA10为多头，低于为空头，相等为平衡。缺失和过期样本不冒充多空。</p><p>多头占比＝多头÷（多头＋空头）。总数＝多头＋空头＋平衡＋缺失。超过50%显示多头占优，低于50%显示空头占优，等于50%显示多空均衡；这是样本数量对比，不是新的交易筛选条件。</p><p>板块综合排序为五周期多头占比的等权平均；任何周期没有有效多空样本，综合值留空并排到末尾。每周期都超过50%为五周期偏多，都低于50%为五周期偏空，其余为混沌分歧。</p><p>范围、板块和搜索影响统计；下方共振分类筛选只影响明细表。左侧选板块只联动右侧分类。刷新调用现有全量同步，沿用其进度与失败提示；页面自动更新只是重读本机数据，不承诺每5分钟拿到新行情。</p>';$('#detailDialog').showModal();icons();
}
function renderOverview(){
 const rows=list(),periods=panoramaPeriods.map(p=>[p.key,p.label]),visible=sort(rows.filter(p=>state.resonance==='all'||p.resonance===state.resonance));
 const filters=chips([['all',`全市场 <b>${rows.length}</b>`],...resonanceLabels.map(label=>[label,`${label} <b>${rows.filter(p=>p.resonance===label).length}</b>`])],state.resonance,'data-resonance');
 const matrix=table([[`品种 <small>${visible.length} 个</small>`,'name',nameCell],...periods.map(([key,label])=>[`${label}<small>EMA10</small>`,'',p=>signalCell(p,key)]),['综合评级','',p=>`<span class="resonance-tag ${p.resonance==='全红共振'?'red':p.resonance==='全绿共振'?'green':''}">${esc(p.resonance)}</span>`]],visible,{id:'cycleMatrix'});
 const legend=`<div class="matrix-legend"><span class="strong-long">强</span><span class="soft-long">偏强</span><span class="soft-short">偏弱</span><span class="strong-short">弱</span><span class="flat">平衡</span><span class="missing">数据不足 / 待核</span><small>点击色块查看依据，点击品种查看完整详情</small></div>`;
 const rules=`<details class="matrix-rules"><summary>强弱口径与数据说明</summary><p>五个周期均沿用 EMA10。强＝完成K线收盘高于EMA10且EMA10上升；弱＝收盘低于EMA10且EMA10下降。EMA同根K的斜率与价格位置同向，“偏强／偏弱”色阶只兼容历史记录。价格等于EMA10为平衡，样本不足或序列陈旧单独标明。</p><p>全红／全绿共振＝五周期价格均在各自EMA10同一侧，包含偏强／偏弱。月周偏空而日、2小时、30分钟偏多为逆市诱多，反向为逆市诱空；其他组合为混沌分歧。“诱多／诱空”只是周期组合名称，不表示已确认存在诱导行为。</p><p>月、周、日采用完成主连K线；2小时、30分钟采用具体合约完成K线。各周期截止时间可能不同，以色块中的实际日期为准。本页观察不改变火筛选或金计划资格。</p></details>`;
 return renderCycleDashboard(rows)+`<section class="cycle-overview"><div class="resonance-toolbar"><span>共振筛选</span>${filters}</div>${matrix}${legend}${rules}</section>`;
}
