 const columns=[['品种','',identity],...strengthPeriods.map(key=>[({month:'月',week:'周',day:'日'}[key])+'斜率','',p=>'<b class="'+side+'">'+((p.trend.slopes[key]>0?'+':'')+p.trend.slopes[key].toFixed(Math.abs(p.trend.slopes[key])<.01?4:3)+'%')+'</b>']),['综合分位','',p=>'<b title="三周期斜率分位等权平均；同向样本 '+p.trend.sample+' 个，不是收益或胜率">'+n(p.trend.score,1)+'</b>'],['60日位置','',trendPositionCell]];
 return rows.length?table(columns,rows.slice(0,5),{sortable:false,preserveOrder:true,id:side==='long'?'strongTrendTable':'weakTrendTable'}):'<div class="empty trend-empty">当前范围没有月、周、日同时满足的'+(side==='long'?'多头':'空头')+'品种</div>';
