 const picker='<div class="strength-picker"><div class="strength-picker-row"><strong>板块</strong><div class="strength-sector-tabs" role="group" aria-label="品种强弱板块">'+groups.map(([key,label])=>'<button data-strength-group="'+esc(key)+'" aria-pressed="'+(state.compareGroup===key)+'" class="'+(state.compareGroup===key?'active':'')+'">'+esc(label)+'</button>').join('')+'</div></div><div class="strength-picker-row observation-pool-row"><strong>观察池</strong><div class="strength-sector-tabs" role="group" aria-label="多空观察池">'+observationPools.map(([key,label])=>'<button data-strength-pool="'+key+'" aria-pressed="'+(state.comparePool===key)+'" class="'+(state.comparePool===key?'active':'')+'">'+label+'</button>').join('')+'</div></div><div class="pool-source caption">'+esc(poolInfo)+'</div><div class="strength-picker-row"><strong>品种</strong><div class="observation-member-list">'+(pool.key==='all'?'<div class="strength-product-tabs">'+rows.map(comparisonButton).join('')+'</div>':memberGroup('long')+memberGroup('short'))+'</div></div></div>';
 const trendGroup=state.comparePool==='month-week-day';
 const controls='<div class="comparison-toolbar">'+chips([['default',trendGroup?'趋势强度排列':'默认排列'],['gainers','涨幅排列'],['losers','跌幅排列']],state.compareOrder,'data-compare-order')+'<button data-follow-leaders aria-pressed="'+state.followQuoteLeaders+'" title="'+(pool.key==='quote'?'自动追踪当前最强和最弱的各6个品种':'恢复本观察池多空各前6个')+'">'+(pool.key==='quote'?(state.followQuoteLeaders?'自动追踪强弱':'恢复追踪强弱'):'恢复本池对比')+'</button><button data-compare-all aria-pressed="'+all+'" '+(rows.length?'':'disabled')+' title="'+(all?'取消':'选择')+'本组全部品种">'+icon(all?'square-check':'square')+(all?'取消全选':'全选')+'</button>'+(totalSelected?'<button data-compare-clear title="清空所有板块中的已选品种">清空对比</button>':'')+'<span class="caption">本组已选 '+selected.length+' / '+rows.length+' · 跨板块共选 '+totalSelected+' 个</span></div>';
