function renderRankings(){
 const tabs=chips([['delta','席位持仓变化'],['amountChange','席位金额变化'],['commodity','商品持仓规模变化'],['amount','席位净名义金额']],state.rank,'data-rank');
 const top='<div class="ranking-typebar"><strong>类型选择</strong>'+tabs+'<span>'+(state.rank==='commodity'?'已取得结算样本':'数据日期 '+esc(state.snapshot.seatDate||'待同步'))+'</span></div>';
 const numberCell=(value,amount=false)=>'<span class="ranking-number '+tone(value)+'">'+(amount?money(value):n(value))+'</span>';
 const common=[['序号','',p=>'<span class="ranking-index">'+p.displayRank+'</span>'],['板块','sector',rankingSectorTag],['品种','name',rankingName]];
 if(state.rank==='commodity'){
  const rows=sort(list().filter(p=>p.marketSamples),state.sort||'marketNominalChange').map((p,i)=>({...p,displayRank:i+1}));
  return '<div class="rankings-page">'+top+note('同一具体合约的持仓量变化 × 当日结算价 × 每点价值，再按品种加总。正值代表持仓规模增加，不代表看多或真实资金净流入；大商所为当前核验主力范围。')+section('商品持仓名义规模变化',table([...common,['持仓变化（手）','marketInterestChange',p=>numberCell(p.marketInterestChange)],['名义规模变化','marketNominalChange',p=>numberCell(p.marketNominalChange,true)],['可比合约数','marketSamples']],rows,{id:'rankingTable',preserveOrder:true}))+'</div>';
 }
 const rows=sort(list().map(p=>grouped(p,state.rankGroup)).filter(p=>p.pairs.length),state.sort||state.rank).map((p,i)=>({...p,displayRank:i+1}));
 const columns=[common[0],['数据日期','seatDate',p=>esc(p.seatDate||'待同步')],...common.slice(1),['净仓（手）','net',p=>numberCell(p.net)],['净仓变化（手）','delta',p=>numberCell(p.delta)],['净名义金额','amount',p=>numberCell(p.amount,true)],['持仓变化金额','amountChange',p=>numberCell(p.amountChange,true)],['双侧样本','',p=>'<span class="ranking-coverage">'+p.pairs.filter(x=>x.complete).length+'/'+p.pairs.length+'</span>'],['明细','',p=>'<button data-seats="'+esc(p.code)+'" title="查看全部合约与会员">'+icon('list-tree')+'</button>']];
 return '<div class="rankings-page">'+top+'<div class="ranking-observation-groups">'+groupChips()+'</div>'+note('金额按公开可比双侧持仓 × 同日合约结算价 × 每点价值估算；持仓变化金额不是真实资金净流入。缺少合约结算价时金额留空。')+section(rankLabel(),table(columns,rows,{id:'rankingTable',preserveOrder:true}), '公开排名 '+(state.snapshot.seatDate||'待同步')+' · 当前 '+rows.length+' 个品种；组别仅为观察标签')+'</div>';
}
