function seatTable(p){const rows=(p?.pairs||[]).filter(x=>(state.rankGroup==='all'||x.groups.includes(state.rankGroup))&&(!state.members.size||state.members.has(x.member)));return table([['席位 / 合约','member',r=>`<b>${esc(r.member)}</b><small>${esc(r.contract)} · ${esc(r.groups.join('、')||'未分组')}</small>`],['公开多头','long',r=>n(r.long)],['公开空头','short',r=>n(r.short)],['净持仓','net',r=>`<span class="${tone(r.net)}">${n(r.net)}</span>`],['净仓变化','delta',r=>`<span class="${tone(r.delta)}">${n(r.delta)}</span>`],['动作','action'],['净名义金额','amount',r=>`<span class="${tone(r.amount)}">${money(r.amount)}</span>`],['结算价','price',r=>n(r.price,3)]],sort(rows,'net'),{id:p?.code?'seats-'+p.code:'seatDetails',preserveOrder:true})}
