 return{title:id==='strengthChart'?'品种走势对比':id?`${d?.name||'品种'} · ${title}`:title,date:s?.selectedDate||state.date,asOf:x?.at(-1)||`行情：${s?.products.map(p=>p.priceTime).filter(Boolean).sort().at(-1)||'待同步'}；席位：${s?.seatDate||'待同步'}；费率及价格时间按行标注`,unit,source:id==='priceChart'?[...new Set(d?.bars[state.period]?.map(b=>b.source)||[])].join('；'):s?.source||'待核',basis,scope:`${state.scope==='all'?'全部期货':state.scope==='commodity'?'商品期货':state.scope==='financial'?'金融期货':'我的自选'}；${state.sector==='all'?'全部板块':state.sector}；${state.rankGroup==='all'?'全部观察组':state.rankGroup}；席位：${[...state.members].join('、')||'全部'}${state.search?'；搜索：'+state.search:''}${$('.product-selector')?'；本页板块：'+($('.picker-boards .active')?.textContent||'全部')+(state.page==='fees'?'；费用品种：'+(state.feeProduct||'全部品种'):''):''}`};
