$('#cancelSync').onclick=async()=>{try{const job=await api('cancel',{});if(state.snapshot)state.snapshot.job=job;updateStatus();toast('已请求取消同步')}catch(e){toast(e.message)}};
$('#sourcesButton').onclick=showSources;
$('#autoToggle').onclick=()=>{state.auto=!state.auto;$('#autoToggle').setAttribute('aria-pressed',String(state.auto));$('#autoToggle').innerHTML=icon(state.auto?'pause':'play')+`<span>${state.auto?'自动更新':'已暂停'}</span>`;icons();updateStatus();if(state.auto)void load()};
$('#exportButton').onclick=async()=>{try{const table=$('#content table');if(!table)return toast('当前页面没有可导出的表格');const rows=[...table.rows].map(r=>[...r.cells].map(c=>c.innerText));const result=await api('export',{title:pages.find(p=>p[0]===state.page)[1],date:state.date,rows,metadata:chartEvidence()});toast('表格已导出：'+result.path)}catch(e){toast(e.message)}};
if(!unified)window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(page!==state.page)setPage(page)});
window.addEventListener('resize',()=>{for(const c of charts.values())c.resize();if(['home','strength'].includes(state.page))requestAnimationFrame(()=>{if(['home','strength'].includes(state.page))void drawCharts()})});
window.addEventListener('pagehide',()=>{trendPage?.stop();marketReadRequests.cancel();strengthReadRequests.cancel();stream?.close();clearInterval(pollTimer);clearInterval(replayTimer);chartRequest++;for(const c of charts.values())c.dispose();charts.clear();chartMetadata.clear()});
window.addEventListener('pageshow',e=>{if(e.persisted){connect();render();void load()}});
window.addEventListener('xiaomu:fire-updated',e=>{if(!e.detail?.rows?.length)return;state.latestFire=e.detail;state.fireVersion++;state.fireDirty=true;state.detailCache.clear();if(state.snapshot){state.snapshot=mergeFireSnapshot(state.snapshot,e.detail);if(active()&&!state.playing&&!state.replayMode)render()}else if(active())void load()});
window.addEventListener('storage',e=>{if(e.key==='wj-fire-revision'){state.fireDirty=true;if(active()&&!state.playing&&!state.replayMode)void load()}});
function startStrengthReplay(){clearInterval(replayTimer);replayTimer=setInterval(()=>{state.replayIndex+=state.replaySpeed;void drawCharts()},800)}
function autoAllowed(){return active()&&(state.page==='strength'?strengthAutoReady({...state,lastLoadedAt:state.lastRefreshStartedAt||state.lastLoadedAt,today:today()}):state.auto&&!state.playing)}
function connect(){stream?.close();clearInterval(pollTimer);stream=new EventSource('/api/market-panorama/events');stream.addEventListener('job',e=>{const j=JSON.parse(e.data);if(state.snapshot)state.snapshot.job=j;updateStatus();if(j.status!=='running'&&(state.closeRefreshRequested||autoAllowed())&&!state.playing&&!state.replayMode&&active()){state.closeRefreshRequested=false;state.detailCache.clear();void load()}});stream.addEventListener('data',()=>{if(autoAllowed()){state.detailCache.clear();void load()}});stream.onerror=()=>{state.connected=false;updateStatus()};stream.onopen=()=>{state.connected=true;updateStatus()};pollTimer=setInterval(()=>{if(autoAllowed()&&(state.page==='strength'||document.visibilityState==='visible'))void load()},30000)}
window.addEventListener('xiaomu:market-connection',()=>{state.detailCache.clear();if(active())void load()});
setInterval(()=>{if(state.page!=='strength'&&state.snapshot?.tqConnection?.selected&&state.auto&&!state.playing&&active()&&document.visibilityState==='visible')void load()},5000);
icons();await load();connect();

mountShell();

export function openMarketPage(page,options={}){if(options.product&&state.product!==options.product){state.product=options.product;clearDetail()}setPage(page,true);queueMicrotask(()=>{for(const c of charts.values())c.resize()});if(state.page!=='monitor'&&(state.fireDirty||Date.now()-state.lastLoadedAt>5000))void load();}
export function getMarketContext(){const focused=['funds','positions','variety','fees'].includes(state.page),p=focused?state.snapshot?.products.find(p=>p.code===state.product):null;return{page:state.page,product:p?.code,symbol:p?`${p.exchange}.${p.contract}`:null,name:p?.name,date:state.date};}
export function pauseMarketSurface(){trendPage?.stop();marketReadRequests.cancel({backgroundOnly:true});strengthReadRequests.cancel();comparisonPending.clear();intradaySeriesPending.clear();clearInterval(replayTimer);state.playing=false;state.replayMode=false;chartRequest++;}
